import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import {
  attenuateMandateToken,
  effectiveAuthority,
  ephemeralKeyFromSeed,
  sealMandateToken,
  tokenBlockHashes,
  tokenHeadHash,
  verifyMandateToken,
  type EffectiveAuthority,
  type MandateToken,
  type PublicKeyEntry,
} from "@pharos/core";

/**
 * MandateToken conformance (Workstream A). The vectors are the contract: the TypeScript SDK and
 * the Python SDK verify the same file with their own implementations. Generated by
 * scripts/gen-mandate-token-vectors.ts from fixed seeds.
 */
interface Vector {
  name: string;
  description: string;
  rootKeyId: string;
  now: string;
  expect: { tenantId?: string; agentId?: string };
  token: MandateToken;
  result: { ok: boolean; code: string | null; effective: EffectiveAuthority | null };
}
const fixture = JSON.parse(readFileSync(new URL("./vectors.json", import.meta.url), "utf8")) as {
  keyset: PublicKeyEntry[];
  vectors: Vector[];
};
const keyset = new Map(fixture.keyset.map((k) => [k.keyId, k]));
const byName = Object.fromEntries(fixture.vectors.map((v) => [v.name, v]));

describe("MandateToken conformance vectors", () => {
  it("covers every structural case the handoff names", () => {
    for (const name of [
      "valid-chain",
      "truncated-chain",
      "widened-scope",
      "expired",
      "wrong-root",
      "replayed-ephemeral-key",
    ])
      expect(byName[name], name).toBeDefined();
  });

  for (const v of fixture.vectors) {
    it(`${v.name}: ${v.description}`, () => {
      const r = verifyMandateToken(v.token, keyset.get(v.rootKeyId)!, new Date(v.now), {
        expect: v.expect,
      });
      expect(r.ok).toBe(v.result.ok);
      expect(r.code).toBe(v.result.code);
      if (v.result.ok) expect(r.effective).toEqual(v.result.effective);
      else expect(r.effective).toBeNull();
    });
  }

  it("the effective authority of the valid chain is the intersection of every block", () => {
    const eff = byName["valid-chain"]!.result.effective!;
    expect(eff.limits).toEqual({
      financialAmount: 5000,
      currency: "USD",
      reversibility: "reversible",
    });
    expect(eff.scope).toEqual({ actionTypes: ["payment.transfer"], resources: ["acct:ops-*"] });
    expect(eff.expiresAt).toBe("2035-11-01T00:00:00.000Z");
    expect(effectiveAuthority(byName["valid-chain"]!.token)).toEqual(eff);
  });

  it("block hashes are the sha256 of each canonical block, and the head hash excludes the proof", () => {
    const t = byName["valid-chain"]!.token;
    const sealed = byName["valid-sealed"]!.token;
    expect(tokenBlockHashes(t)).toHaveLength(3);
    expect(tokenBlockHashes(t)).toEqual(tokenBlockHashes(sealed));
    expect(tokenHeadHash(t)).toBe(tokenHeadHash(sealed));
    expect(
      verifyMandateToken(t, keyset.get(t.authority.keyId)!, new Date(byName["valid-chain"]!.now))
        .blockHashes,
    ).toEqual(tokenBlockHashes(t));
  });
});

describe("MandateToken codec behaviour", () => {
  const valid = byName["valid-chain"]!;
  const root = keyset.get("mandate:acme#v1")!;
  const now = new Date(valid.now);

  it("verifies against a raw Ed25519 public key as well as a keyset entry", () => {
    const spki = Buffer.from(root.publicKey, "base64");
    const raw = new Uint8Array(spki.subarray(spki.length - 32));
    expect(verifyMandateToken(valid.token, raw, now).ok).toBe(true);
    expect(verifyMandateToken(valid.token, new Uint8Array(32), now).code).toBe("root-signature");
  });

  it("attenuate refuses a widening block and a sealed token, and never retains the signing key", () => {
    expect(() =>
      attenuateMandateToken(valid.token, {
        checks: [{ kind: "limit", value: { financialAmount: 6000 } }],
        issuedAt: now.toISOString(),
      }),
    ).toThrow(/widens/);
    expect(() =>
      attenuateMandateToken(valid.token, {
        checks: [{ kind: "scope", value: { actionTypes: ["payment."] } }],
        issuedAt: now.toISOString(),
      }),
    ).toThrow(/widens/);
    expect(() =>
      attenuateMandateToken(sealMandateToken(valid.token), {
        checks: [],
        issuedAt: now.toISOString(),
      }),
    ).toThrow(/sealed/);
    const next = attenuateMandateToken(
      valid.token,
      { checks: [{ kind: "limit", value: { financialAmount: 10 } }], issuedAt: now.toISOString() },
      ephemeralKeyFromSeed(Buffer.alloc(32, 7)),
    );
    expect(next.proof).toEqual({ kind: "next", secret: Buffer.alloc(32, 7).toString("base64") });
    expect(JSON.stringify(next)).not.toContain((valid.token.proof as { secret: string }).secret);
    expect(verifyMandateToken(next, root, now).effective?.limits.financialAmount).toBe(10);
  });

  it("a no-op block (same limits) is not a widening; a scope narrowed to a prefix of a prefix is fine", () => {
    const t = attenuateMandateToken(valid.token, {
      checks: [
        { kind: "limit", value: { financialAmount: 5000, currency: "USD" } },
        { kind: "scope", value: { resources: ["acct:ops-eu-*", "acct:ops-1"] } },
      ],
      issuedAt: now.toISOString(),
    });
    const r = verifyMandateToken(t, root, now);
    expect(r.ok).toBe(true);
    expect(r.effective?.scope.resources).toEqual(["acct:ops-eu-*", "acct:ops-1"]);
  });

  it("rejects a chain longer than the ceiling", () => {
    let t = byName["authority-only"]!.token;
    for (let i = 0; i < 17; i++)
      t = attenuateMandateToken(t, { checks: [], issuedAt: now.toISOString() });
    expect(verifyMandateToken(t, root, now).code).toBe("too-many-blocks");
    expect(verifyMandateToken(t, root, now, { maxBlocks: 17 }).ok).toBe(true);
  });

  it("a sealed token verifies, and a sealed token with a forged seal does not", () => {
    const sealed = byName["valid-sealed"]!.token;
    expect(verifyMandateToken(sealed, root, now).ok).toBe(true);
    const forged = {
      ...sealed,
      proof: { kind: "sealed" as const, signature: Buffer.alloc(64, 1).toString("base64") },
    };
    expect(verifyMandateToken(forged, root, now).code).toBe("proof");
  });
});
